CREATE TABLE documents(id UUID PRIMARY KEY,owner_id UUID NOT NULL,original_name VARCHAR(255) NOT NULL,content_type VARCHAR(100) NOT NULL,size_bytes BIGINT NOT NULL,storage_key VARCHAR(500) NOT NULL UNIQUE,checksum VARCHAR(64) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT ck_document_size CHECK(size_bytes>0));
CREATE TABLE ai_jobs(id UUID PRIMARY KEY,requested_by UUID NOT NULL,document_id UUID REFERENCES documents(id),type VARCHAR(40) NOT NULL,status VARCHAR(20) NOT NULL,request_json TEXT,result_reference VARCHAR(500),error_code VARCHAR(100),error_message VARCHAR(1000),created_at TIMESTAMP WITH TIME ZONE NOT NULL,started_at TIMESTAMP WITH TIME ZONE,completed_at TIMESTAMP WITH TIME ZONE,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,version BIGINT NOT NULL DEFAULT 0,CONSTRAINT ck_job_type CHECK(type IN('QUESTION_GENERATION','ANALYSIS','CHAT')),CONSTRAINT ck_job_status CHECK(status IN('PENDING','PROCESSING','COMPLETED','FAILED')));
CREATE TABLE ai_results(id UUID PRIMARY KEY,job_id UUID NOT NULL UNIQUE REFERENCES ai_jobs(id) ON DELETE CASCADE,result_json TEXT NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE processed_events(event_id UUID PRIMARY KEY,event_type VARCHAR(100) NOT NULL,processed_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX idx_documents_owner ON documents(owner_id,created_at);CREATE INDEX idx_jobs_user_status ON ai_jobs(requested_by,status,created_at);CREATE INDEX idx_jobs_document ON ai_jobs(document_id);
